let LOCALE = 'en';

function setLocale(l) {
    LOCALE = (l === 'en' || I18N[l]) ? l : 'en';
    document.documentElement.lang = LOCALE;
}

function t(key) {
    const dict = I18N[LOCALE];
    return (dict && dict[key]) || key;
}
window.t = t;

// Static markup. data-i18n: the original trimmed textContent is the key.
// data-i18n-html: the original innerHTML (whitespace-collapsed) is the key.
// data-i18n-title: the original title attribute is the key.
// Each original is captured ONCE, so switching back to English is reversible.
function applyStaticI18n() {
    document.querySelectorAll('[data-i18n]').forEach((el) => {
        if (!el.dataset.i18nKey) el.dataset.i18nKey = el.textContent.trim();
        el.textContent = t(el.dataset.i18nKey);
    });
    document.querySelectorAll('[data-i18n-html]').forEach((el) => {
        if (!el.dataset.i18nKey) el.dataset.i18nKey = el.innerHTML.trim().replace(/\s+/g, ' ');
        el.innerHTML = t(el.dataset.i18nKey);
    });
    document.querySelectorAll('[data-i18n-title]').forEach((el) => {
        if (!el.dataset.i18nTitle) el.dataset.i18nTitle = el.title;
        el.title = t(el.dataset.i18nTitle);
    });
}

// ── Fleet wiring: carino-lang.js resolves the language and fires langchange.
function currentFleetLang() { return (window.CarinoLang && window.CarinoLang.current) || 'en'; }

function applyI18n() {
    setLocale(currentFleetLang());
    applyStaticI18n();
    // Re-render the chrome the page script generates (swatch titles, copy-button
    // aria-labels, the active tab pane).
    if (window.brandingRelocalize) window.brandingRelocalize();
}

// carino-lang.js is deferred and runs before this (also deferred) script, so
// CarinoLang exists by DOMContentLoaded; re-apply on every fleet switch.
document.addEventListener('DOMContentLoaded', applyI18n);
window.addEventListener('carino:langchange', applyI18n);
